<script setup lang="ts">
import { computed, ref } from 'vue'
import { useMissionStore } from '../stores/mission'
import { durationLabel } from '../utils/replay'
import Header from '../components/layout/DashboardHeader.vue'
import AircraftPanel from '../components/aircraft/AircraftPanel.vue'
import ReplaySurface from '../components/replay/ReplaySurface.vue'
import ReplayControls from '../components/replay/ReplayControls.vue'
import AltitudeChart from '../components/replay/AltitudeChart.vue'
import AnalysisPanel from '../components/analysis/AnalysisPanel.vue'
import EventLog from '../components/analysis/EventLog.vue'
import Icon from '../components/common/AppIcon.vue'
const store = useMissionStore(), aircraftPanel = ref<InstanceType<typeof AircraftPanel>>()
const kpis = computed(() => [{ label: 'AIRCRAFT TRACKED', value: String(store.mission.aircraft.filter(a => store.mission.telemetry.some(t => t.aircraftId === a.id)).length).padStart(2, '0'), icon: 'Plane', note: 'Configured flight tracks', tone: 'blue' }, { label: 'FLIGHT DURATION', value: durationLabel(store.duration), icon: 'Clock3', note: 'Shared mission timeline', tone: 'cyan' }, { label: 'SHOT EVENTS', value: String(store.mission.events.length).padStart(2, '0'), icon: 'Crosshair', note: 'Recorded training events', tone: 'blue' }, { label: 'DATA COMPLETENESS', value: `${store.report.completeness}%`, icon: 'Activity', note: `${store.report.missingSamples} estimated missing samples`, tone: 'green' }, { label: 'UNVERIFIED EVENTS', value: String(store.mission.events.length).padStart(2, '0'), icon: 'ShieldCheck', note: 'Awaiting certified evidence', tone: 'amber' }])
</script>
<template><div class="app-shell"><Header @import="aircraftPanel?.open()"/><main><div class="page-heading"><div><div class="eyebrow">MISSION CONTROL <span>/ POST-FLIGHT REVIEW</span></div><h2>{{ store.mission.name }}<span class="status-badge" :class="store.mission.simulated ? 'simulated' : 'neutral'">{{ store.mission.simulated ? 'SIMULATED DATA' : 'USER IMPORTS' }}</span></h2><p>Review the flight. Verify the data. Trust the evidence.</p></div><button class="button" @click="store.exportReport()"><Icon name="Download" :size="16"/>Export report</button></div><section class="kpi-grid" aria-label="Mission statistics"><article v-for="k in kpis" :key="k.label" class="kpi-card"><div><span class="kpi-label">{{ k.label }}</span><div class="kpi-value">{{ k.value }}</div><span class="kpi-note"><i :class="k.tone"></i>{{ k.note }}</span></div><div class="kpi-icon" :class="k.tone"><Icon :name="k.icon" :size="22"/></div></article></section>
<div class="workspace-grid fixed-workspace"><AircraftPanel ref="aircraftPanel"/><section class="center-column"><div class="panel replay-panel"><div class="replay-heading"><div class="inline"><Icon name="Radio" :size="17"/><h2>Flight replay</h2><span class="outline-tag">3D</span></div><div class="inline camera-tools"><select v-model="store.cameraMode" aria-label="Camera mode"><option value="thailand">Thailand · tilted</option><option value="overview">Mission overview</option><option v-for="a in store.mission.aircraft" :key="a.id" :value="a.id">Follow {{ a.callsign }}</option><option value="free">Free camera</option><option value="top">Top view</option><option value="side">Side view</option></select><button class="icon-button" aria-label="Toggle flight paths" :aria-pressed="store.showPaths" :class="{ active: store.showPaths }" @click="store.showPaths = !store.showPaths"><Icon name="Layers" :size="16"/></button><button class="icon-button" aria-label="Reset camera" @click="store.resetCamera()"><Icon name="RotateCcw" :size="16"/></button></div></div><div class="viewer-region"><ReplaySurface/><div v-if="!store.mission.telemetry.length" class="no-telemetry">No telemetry · Import a track or load demo data</div></div><div class="aircraft-state-strip"><div v-for="s in store.aircraftStates" :key="s.aircraft.id" class="aircraft-state"><div><span class="aircraft-dot" :style="{ background: s.aircraft.color }"></span><strong>{{ s.aircraft.callsign }}</strong><span class="small muted">{{ s.sample ? s.sample.interpolated ? 'INTERPOLATED' : 'SAMPLE' : 'NO SAMPLE' }}</span></div><div class="telemetry-numbers"><span>ALT <b>{{ s.sample ? Math.round(s.sample.altitude).toLocaleString() : '—' }} <small>m</small></b></span><span>HDG <b>{{ s.sample?.heading !== undefined ? s.sample.heading.toFixed(0) + '°' : '—' }}</b></span><span>P / R <b>{{ s.sample?.pitch !== undefined ? `${s.sample.pitch.toFixed(0)}° / ${s.sample.roll?.toFixed(0) ?? '—'}°` : '— / —' }}</b></span></div></div></div><ReplayControls/></div></section><AnalysisPanel/></div><div class="panel chart-panel mission-altitude-panel"><div class="chart-heading"><h3>Altitude profile <span class="muted">/ meters</span></h3><div class="inline"><span v-for="a in store.mission.aircraft" :key="a.id" class="chart-legend"><i :style="{ background: a.color }"></i>{{ a.callsign }}</span></div></div><AltitudeChart/></div><EventLog/><footer class="app-footer"><span><Icon name="ShieldCheck" :size="13"/>Verification prototype · No operational assessment capability</span><span>Source: {{ store.mission.source }} <span class="footer-dot">·</span> All times UTC</span></footer></main>
<div class="toast-stack" aria-live="polite"><div v-for="n in store.notifications" :key="n.id" class="toast" :class="{ error: n.error }"><Icon :name="n.error ? 'AlertTriangle' : 'Check'" :size="17"/>{{ n.message }}<button class="icon-button" aria-label="Dismiss notification" @click="store.notifications = store.notifications.filter(t => t.id !== n.id)"><Icon name="X" :size="14"/></button></div></div>
<div v-if="store.settingsOpen" class="modal-backdrop" @click.self="store.settingsOpen = false" @keydown.esc="store.settingsOpen = false"><section class="modal settings-modal" role="dialog" aria-modal="true" aria-labelledby="settings-title"><div class="section-heading"><h2 id="settings-title">Workspace settings</h2><button class="icon-button" aria-label="Close settings" @click="store.settingsOpen = false"><Icon name="X"/></button></div><label class="toggle-row">Show flight paths<input v-model="store.showPaths" type="checkbox"></label><label class="toggle-row">Show aircraft labels<input v-model="store.showLabels" type="checkbox"></label><label>Mission name<input v-model="store.mission.name"></label><div class="schema-hint"><strong>Local prototype</strong><span>Data stays in browser memory. Reload resets this session. No AI or simulator backend is connected.</span></div><button class="button primary full" @click="store.settingsOpen = false">Done</button></section></div></div></template>
